import{_ as e,o as t,c as o,a5 as n}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"HJ105 记负均正II","description":"描述 输入 n 个整型数，统计其中的负数个数并求所有非负数的平均值，结果保留一位小数，如果没有非负数，则平均值为0 本题有多组输入数据，输入到文件末尾。 数据范围： 输入描述： 输入任意个整数，每行输入一个。 输出描述： 输出负数个数以及所有非负数的平均值 示例1 输入： 13。","frontmatter":{"title":"HJ105 记负均正II","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"描述 输入 n 个整型数，统计其中的负数个数并求所有非负数的平均值，结果保留一位小数，如果没有非负数，则平均值为0 本题有多组输入数据，输入到文件末尾。 数据范围： 输入描述： 输入任意个整数，每行输入一个。 输出描述： 输出负数个数以及所有非负数的平均值 示例1 输入： 13。","sidebarWeight":27,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为入门题/HJ105 记负均正II.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ105 记负均正II.md","filePath":"posts/前端面试与实战/03-算法训练/华为入门题/HJ105 记负均正II.md"}'),r={name:"posts/前端面试与实战/03-算法训练/华为入门题/HJ105 记负均正II.md"};function i(s,a,l,h,d,p){return t(),o("div",null,[...a[0]||(a[0]=[n('<div><h1 id="hj105-记负均正ii" tabindex="-1">HJ105 记负均正II <a class="header-anchor" href="#hj105-记负均正ii" aria-label="Permalink to &quot;HJ105 记负均正II&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ105 记负均正II”的核心思路，并能把它用于实际开发或面试表达。</p></blockquote><blockquote><p>说明：原 OneNote 中有图片引用，但图片未包含在导出目录中；本页保留了可用的文字与代码内容。 <strong>描述</strong> 输入 n 个整型数，统计其中的负数个数并求所有非负数的平均值，结果保留一位小数，如果没有非负数，则平均值为0 本题有多组输入数据，输入到文件末尾。 数据范围：</p></blockquote><p><strong>输入描述：</strong> 输入任意个整数，每行输入一个。 <strong>输出描述：</strong> 输出负数个数以及所有非负数的平均值 <strong>示例1</strong> 输入： -13-4-7 ==复制== 输出： 30.0 ==复制== <strong>示例2</strong> 输入： -1212 ==复制== 输出： 11.5</p><p>import sys</p><h1 id="初始化负数计数器" tabindex="-1">初始化负数计数器 <a class="header-anchor" href="#初始化负数计数器" aria-label="Permalink to &quot;初始化负数计数器&quot;">​</a></h1><p>count = 0</p><h1 id="初始化存储非负数的列表" tabindex="-1">初始化存储非负数的列表 <a class="header-anchor" href="#初始化存储非负数的列表" aria-label="Permalink to &quot;初始化存储非负数的列表&quot;">​</a></h1><p>non_negative_nums = []</p><h1 id="从标准输入逐行读取数据" tabindex="-1">从标准输入逐行读取数据 <a class="header-anchor" href="#从标准输入逐行读取数据" aria-label="Permalink to &quot;从标准输入逐行读取数据&quot;">​</a></h1><p>for line in sys.stdin:</p><h1 id="将读取的行去除空白字符后转换为整数" tabindex="-1">将读取的行去除空白字符后转换为整数 <a class="header-anchor" href="#将读取的行去除空白字符后转换为整数" aria-label="Permalink to &quot;将读取的行去除空白字符后转换为整数&quot;">​</a></h1><p>num = int(line.strip())</p><h1 id="如果数字是负数-则增加负数计数器" tabindex="-1">如果数字是负数，则增加负数计数器 <a class="header-anchor" href="#如果数字是负数-则增加负数计数器" aria-label="Permalink to &quot;如果数字是负数，则增加负数计数器&quot;">​</a></h1><p>if num &lt; 0: count += 1</p><h1 id="否则-如果数字是非负数-包括0-则添加到非负数列表中" tabindex="-1">否则，如果数字是非负数（包括0），则添加到非负数列表中 <a class="header-anchor" href="#否则-如果数字是非负数-包括0-则添加到非负数列表中" aria-label="Permalink to &quot;否则，如果数字是非负数（包括0），则添加到非负数列表中&quot;">​</a></h1><p>else: non_negative_nums.append(num)</p><h1 id="打印负数的总个数" tabindex="-1">打印负数的总个数 <a class="header-anchor" href="#打印负数的总个数" aria-label="Permalink to &quot;打印负数的总个数&quot;">​</a></h1><p>print(count)</p><h1 id="如果非负数列表不为空-则计算平均值" tabindex="-1">如果非负数列表不为空，则计算平均值 <a class="header-anchor" href="#如果非负数列表不为空-则计算平均值" aria-label="Permalink to &quot;如果非负数列表不为空，则计算平均值&quot;">​</a></h1><p>if len(non_negative_nums) &gt; 0: average = sum(non_negative_nums) / len(non_negative_nums) else:</p><h1 id="如果非负数列表为空-则平均值设为0-0" tabindex="-1">如果非负数列表为空，则平均值设为0.0 <a class="header-anchor" href="#如果非负数列表为空-则平均值设为0-0" aria-label="Permalink to &quot;如果非负数列表为空，则平均值设为0.0&quot;">​</a></h1><p>average = 0.0</p><h1 id="打印非负数的平均值-保留一位小数" tabindex="-1">打印非负数的平均值，保留一位小数 <a class="header-anchor" href="#打印非负数的平均值-保留一位小数" aria-label="Permalink to &quot;打印非负数的平均值，保留一位小数&quot;">​</a></h1><p>print(f&quot;{average:.1f}&quot;)</p></div>',1)])])}const _=e(r,[["render",i]]);export{c as __pageData,_ as default};
